mapper.select:
select delivery_id, webhook_id, event_id, event_type, source, status, attempt,
       http_status, error_message, request_id, next_retry_at, create_time, update_time
from crm_outbound_webhook_delivery
where tenant_id = #{tenantId}
  and webhook_id = #{webhookId}

    and status = #{status}

order by create_time desc

mapper.insert:
insert into crm_outbound_webhook_delivery (
    delivery_id, tenant_id, webhook_id, event_id, event_type, source, status, attempt,
    http_status, error_message, request_id, next_retry_at, payload_json, create_time, update_time
) values (
    #{deliveryId}, #{tenantId}, #{webhookId}, #{eventId}, #{eventType}, #{source}, #{status}, #{attempt},
    #{httpStatus}, #{errorMessage}, #{requestId}, #{nextRetryAt}, #{payloadJson}, #{createTime}, #{updateTime}
)
on conflict (tenant_id, webhook_id, event_id) do nothing
